#include <Cellerator/compiler/ir/realization/implement_prepared_stage_graphs_v1.hh>
#include <set>
#include <tuple>
namespace cellerator::compiler::ir::realization::v1 {namespace{stage_graph_status_v1 fail(stage_graph_status_v1 s,std::string*e,const char*m)noexcept{if(e)*e=m;return s;}}
stage_graph_status_v1 validate_prepared_stage_graph_v1(const prepared_stage_graph_v1&g,std::string*e)noexcept{if(!valid(g.identity)||g.stages.empty())return fail(stage_graph_status_v1::invalid_identity,e,"graph identity and stages required");std::set<std::tuple<std::uint64_t,std::uint64_t>>ids;std::set<std::uint32_t>profiles;for(std::size_t i=0;i<g.stages.size();++i){const auto&s=g.stages[i];if(!valid(s.identity)||!valid(s.candidate)||!valid(s.binding)||!ids.emplace(s.identity.high,s.identity.low).second)return fail(stage_graph_status_v1::duplicate_stage,e,"unique stage, candidate, binding required");std::set<std::uint32_t>deps;for(auto d:s.dependencies)if(d>=i)return fail(stage_graph_status_v1::forward_dependency,e,"dependencies must precede stage");else if(!deps.insert(d).second)return fail(stage_graph_status_v1::duplicate_dependency,e,"duplicate dependency");if(!valid(s.input_order.identity)||!valid(s.output_order.identity))return fail(stage_graph_status_v1::invalid_order,e,"input/output orders required");if(!s.structure_epoch)return fail(stage_graph_status_v1::invalid_epoch,e,"structure epoch required");if(!s.range.global_count||!s.range.local_count||s.range.local_count>s.range.global_count)return fail(stage_graph_status_v1::invalid_range,e,"valid global/local ranges required");if(!profiles.insert(s.profiler_index).second)return fail(stage_graph_status_v1::duplicate_profiler_index,e,"profiler indices unique");}if(e)e->clear();return stage_graph_status_v1::valid;}
stage_graph_status_v1 compare_program_v2_graph_v1(const prepared_stage_graph_v1&g,const cellerator::execution::program::prepared_program_v2&p,std::string*e)noexcept{auto s=validate_prepared_stage_graph_v1(g,e);if(s!=stage_graph_status_v1::valid)return s;if(p.version!=2||p.stage_count!=g.stages.size()||(!p.stages&&p.stage_count))return fail(stage_graph_status_v1::program_v2_mismatch,e,"program_v2 shape mismatch");for(std::size_t i=0;i<g.stages.size();++i){const auto&a=g.stages[i];const auto&b=p.stages[i];if(b.stable_stage_id!=a.identity.low||b.candidate_id!=a.candidate.low||b.binding_index!=a.binding.low||b.required_workspace_bytes!=a.workspace_bytes||b.dependency_count!=a.dependencies.size())return fail(stage_graph_status_v1::program_v2_mismatch,e,"program_v2 stage mismatch");}if(e)e->clear();return stage_graph_status_v1::valid;}
} // namespace cellerator::compiler::ir::realization::v1
